{
  "findings": [
    {
      "ref": "[D523]",
      "area": "contact",
      "claim": "A parent reports that Roblox allows voice chat with strangers and it can be turned off.",
      "stance": "risk",
      "quote": "Roblox has social features like text chat and voice chat in some games. While these features encourage social interaction, they also open the door to kids talking to people they don't know and possibly cyberbullying."
    },
    {
      "ref": "[D523]",
      "area": "money",
      "claim": "A parent reports that Roblox pushes in-app purchases of Robux and uses social pressure to encourage spending.",
      "stance": "risk",
      "quote": "Roblox encourages spending on its virtual currency, \"Robux,\" through limited-time events, exclusive items, and social pressure. Many platforms like this use \"freemium\" features, where spending money enhances the experience, so it's important to set boundaries early on."
    },
    {
      "ref": "[D523]",
      "area": "data",
      "claim": "A parent reports that Roblox collects user data and shares it with third parties for advertising, and that data can be deleted.",
      "stance": "neutral",
      "quote": "Roblox encourages spending on its virtual currency, \"Robux,\" through limited-time events, exclusive items, and social pressure. Many platforms like this use \"freemium\" features, where spending money enhances the experience, so it's important to set boundaries early on."
    },
    {
      "ref": "[D523]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox's age gating is not fully effective in practice, as inappropriate content can still appear in games rated for younger ages.",
      "stance": "risk",
      "quote": "Roblox doesn't have a strict age minimum, but it does use different ratings for game content: * All Ages: Mild content, light fantasy violence. * 9+: May include more fantasy violence. * 13+: Contains more intense content and social interactions. * 17+: Mature content, requiring age verification. While these Roblox experience ratings aim to guide users toward age-appropriate games, it's possible for inappropriate content to slip through."
    },
    {
      "ref": "[D523]",
      "area": "content",
      "claim": "A parent reports that kids can encounter inappropriate content such as sexual themes, violence, bullying, and hate speech in Roblox games.",
      "stance": "risk",
      "quote": "Because Roblox is user-generated, kids may still run into inappropriate content despite the platform's safety filters. This includes \"condo games\" (which usually feature adult themes and sexual content), violent games, gambling-style play, and even games that may have bullying or hate speech."
    },
    {
      "ref": "[D523]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced safety concerns and regulatory scrutiny over content moderation and spending practices.",
      "stance": "risk",
      "quote": "Following safety concerns, Roblox is rolling out new protections for under-13 users in November and December 2024. These updates include mandatory age ratings for games, limits on social spaces, and restrictions on unmoderated content. Since these changes are new and won't be fully enforced until 2025, we're not sure what their impact will be."
    }
  ]
}
